#include "internal.h"
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <string.h>
#include <zlib.h>

/* ZIP32, stored or raw DEFLATE. Entry names are generated by our EPUB writer.
 * Format: https://pkware.cachefly.net/webdocs/casestudies/APPNOTE.TXT
 * We use zlib, already required by the PDF engine, for compression and CRC.
 * This also avoids the no-op compression flag in the bundled PDF ZIP writer. */
struct PD_Zip { FILE *file;fz_buffer *directory;uint64_t offset;unsigned entries; };
static void le16(unsigned char *p,unsigned n){p[0]=(unsigned char)n;p[1]=(unsigned char)(n>>8);}
static void le32(unsigned char *p,uint32_t n){le16(p,n);le16(p+2,n>>16);}
static void put(fz_context *ctx,PD_Zip *z,const void *p,size_t n) {
    if(z->offset+n>UINT32_MAX)fz_throw(ctx,FZ_ERROR_LIMIT,"EPUB exceeds the 4 GiB archive limit");
    if(fwrite(p,1,n,z->file)!=n)fz_throw(ctx,FZ_ERROR_SYSTEM,"Cannot write EPUB: %s",strerror(errno));
    z->offset+=n;
}
PD_Zip *pd_zip_open(fz_context *ctx,const char *path) {
    PD_Zip *z=fz_calloc(ctx,1,sizeof(*z));
    fz_try(ctx) {
        z->file=fopen(path,"wb");
        if(!z->file)fz_throw(ctx,FZ_ERROR_SYSTEM,"Cannot open EPUB: %s",strerror(errno));
        z->directory=fz_new_buffer(ctx,4096);
    }
    fz_catch(ctx){pd_zip_drop(ctx,z);fz_rethrow(ctx);}
    return z;
}
void pd_zip_entry(fz_context *ctx,PD_Zip *z,const char *name,fz_buffer *data,int compress) {
    unsigned char *source=NULL;size_t size=fz_buffer_storage(ctx,data,&source),namelen=strlen(name);
    if(size>UINT_MAX/2 || namelen>UINT16_MAX || z->entries>=UINT16_MAX)
        fz_throw(ctx,FZ_ERROR_LIMIT,"EPUB archive limits exceeded");
    unsigned char *packed=NULL;fz_var(packed);size_t packed_size=size;fz_var(packed_size);
    unsigned method=0;fz_var(method);
    fz_try(ctx) {
        if(compress && size) {
            uLong bound=compressBound((uLong)size);packed=fz_malloc(ctx,(size_t)bound);
            z_stream stream={0};stream.next_in=source;stream.avail_in=(uInt)size;
            stream.next_out=packed;stream.avail_out=(uInt)bound;
            if(deflateInit2(&stream,6,Z_DEFLATED,-MAX_WBITS,8,Z_DEFAULT_STRATEGY)!=Z_OK)
                fz_throw(ctx,FZ_ERROR_SYSTEM,"Cannot start EPUB compression");
            int rc=deflate(&stream,Z_FINISH);packed_size=(size_t)stream.total_out;deflateEnd(&stream);
            if(rc!=Z_STREAM_END)fz_throw(ctx,FZ_ERROR_SYSTEM,"Cannot compress EPUB entry");
            if(packed_size<size)method=8;else packed_size=size;
        }
        uint32_t crc=(uint32_t)crc32(0,source,(uInt)size),offset=(uint32_t)z->offset;
        unsigned char local[30]={0};le32(local,0x04034b50);le16(local+4,20);le16(local+6,0x800);
        le16(local+8,method);le16(local+12,0x21);le32(local+14,crc);le32(local+18,(uint32_t)packed_size);
        le32(local+22,(uint32_t)size);le16(local+26,(unsigned)namelen);
        put(ctx,z,local,sizeof(local));put(ctx,z,name,namelen);put(ctx,z,method?packed:source,packed_size);
        unsigned char central[46]={0};le32(central,0x02014b50);le16(central+4,20);le16(central+6,20);le16(central+8,0x800);
        le16(central+10,method);le16(central+14,0x21);le32(central+16,crc);le32(central+20,(uint32_t)packed_size);
        le32(central+24,(uint32_t)size);le16(central+28,(unsigned)namelen);le32(central+42,offset);
        fz_append_data(ctx,z->directory,central,sizeof(central));fz_append_data(ctx,z->directory,name,namelen);z->entries++;
    }
    fz_always(ctx) fz_free(ctx,packed);
    fz_catch(ctx) fz_rethrow(ctx);
}
void pd_zip_finish(fz_context *ctx,PD_Zip *z) {
    uint32_t offset=(uint32_t)z->offset;unsigned char *data=NULL;
    size_t size=fz_buffer_storage(ctx,z->directory,&data);put(ctx,z,data,size);
    unsigned char end[22]={0};le32(end,0x06054b50);le16(end+8,z->entries);le16(end+10,z->entries);
    le32(end+12,(uint32_t)size);le32(end+16,offset);put(ctx,z,end,sizeof(end));
    int error=fclose(z->file);z->file=NULL;
    if(error)fz_throw(ctx,FZ_ERROR_SYSTEM,"Cannot finish EPUB: %s",strerror(errno));
}
void pd_zip_drop(fz_context *ctx,PD_Zip *z) {
    if(!z)return;
    if(z->file)fclose(z->file);
    fz_drop_buffer(ctx,z->directory);fz_free(ctx,z);
}
